"""Lossless mixed finite differences of the late-transient response."""
import json,lzma,time,hashlib
import numpy as np
from architecture import ROOT
p=ROOT/'out/v147/tail.raw.bin';raw=p.read_bytes();assert len(raw)==289997228 and raw[:8]==b'TAILRAW1';start=time.process_time();a=np.frombuffer(raw[428:],dtype='<i2').reshape(160,160,59,24,4);v=a.copy();v[:,:,:,:,1:]-=a[:,:,:,:,:-1];v[:,:,:,1:]-=v[:,:,:,:-1].copy();v[:,:,1:]-=v[:,:,:-1].copy();encoded=lzma.compress(v.tobytes(),preset=6,check=lzma.CHECK_CRC32);b=np.frombuffer(lzma.decompress(encoded),dtype='<i2').reshape(a.shape);b=np.cumsum(b,axis=2,dtype=np.int32).astype('<i2');b=np.cumsum(b,axis=3,dtype=np.int32).astype('<i2');b=np.cumsum(b,axis=4,dtype=np.int32).astype('<i2');assert np.array_equal(a,b);dest=ROOT/'out/v147/tail-difference.bin';dest.write_bytes(b'TAILXZ01'+raw[8:428]+encoded);r={'state':'complete','scope':'architecture-only lossless late-anchor asset, runtime loading and total budget pending','bytes':dest.stat().st_size,'raw_bytes':len(raw),'decoded_sha256':hashlib.sha256(raw[428:]).hexdigest(),'asset_sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'lossless_roundtrip':True,'delta_min':int(a.min()),'delta_max':int(a.max()),'nonzero_fraction':float(np.mean(a!=0)),'cpu_seconds':time.process_time()-start};(ROOT/'reports/V147-tail-compression.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r),flush=True)
